package org.deeptimeline.app
import java.math.BigDecimal
import java.math.BigInteger
import java.math.MathContext
import java.math.RoundingMode
import java.time.Instant
import java.time.LocalDateTime
import java.time.ZoneOffset
private data class ExactRatio(val n:BigInteger,val d:BigInteger):Comparable<ExactRatio>{init{require(d.signum()>0)};override fun compareTo(other:ExactRatio):Int=n.multiply(other.d).compareTo(other.n.multiply(d));fun times(other:ExactRatio):ExactRatio=of(n.multiply(other.n),d.multiply(other.d));fun div(other:ExactRatio):ExactRatio{require(other.n.signum()!=0){"Division by zero"};return of(n.multiply(other.d),d.multiply(other.n))};fun power(exponent:Int):ExactRatio{require(exponent in -4096..4096){"Exponent magnitude must not exceed 4096"};return if(exponent>=0)of(n.pow(exponent),d.pow(exponent)) else {require(n.signum()!=0){"Division by zero"};of(d.pow(-exponent),n.pow(-exponent))}};fun asDouble():Double=BigDecimal(n).divide(BigDecimal(d),MathContext.DECIMAL64).toDouble();companion object{fun of(num:BigInteger,den:BigInteger):ExactRatio{require(den.signum()!=0){"Division by zero"};val sign=if(den.signum()<0)BigInteger.valueOf(-1) else BigInteger.ONE;val a=num.multiply(sign);val b=den.multiply(sign);val gcd=a.gcd(b);return ExactRatio(a.divide(gcd),b.divide(gcd))};fun decimal(s:String):ExactRatio{val value=BigDecimal(s);require(value.precision()<=256){"Numeric expression has too many digits"};require(value.scale() in -4096..4096){"Scientific exponent magnitude must not exceed 4096"};val scale=value.scale();return if(scale>=0)of(value.unscaledValue(),BigInteger.TEN.pow(scale)) else of(value.unscaledValue().multiply(BigInteger.TEN.pow(-scale)),BigInteger.ONE)}}}
private class ScaleExpression(raw:String){private val source=raw.filterNot{it.isWhitespace()};private var index=0;fun parse():ExactRatio{require(source.isNotEmpty()&&source.length<=256){"Visibility expression must contain 1–256 characters"};val result=quotient();require(index==source.length){"Unexpected symbol at position ${index+1}"};require(result.n.signum()>0){"Visibility threshold must be positive"};return result};private fun quotient():ExactRatio{var result=power();while(index<source.length&&source[index]=='/'){index++;result=result.div(power())};return result};private fun power():ExactRatio{var base=atom();if(index<source.length&&source[index]=='^'){index++;val wrapped=index<source.length&&source[index]=='(';if(wrapped)index++;val start=index;if(index<source.length&&(source[index]=='+'||source[index]=='-'))index++;while(index<source.length&&source[index].isDigit())index++;require(index>start&&source.substring(start,index).any{it.isDigit()}){"Exponent must be an integer"};val exponent=source.substring(start,index).toIntOrNull()?:throw IllegalArgumentException("Exponent outside supported range");if(wrapped){require(index<source.length&&source[index]==')'){"Missing ')' after exponent"};index++};base=base.power(exponent)};return base};private fun atom():ExactRatio{require(index<source.length){"Missing number"};if(source[index]=='('){index++;val result=quotient();require(index<source.length&&source[index]==')'){"Missing ')'"};index++;return result};val repeating=Regex("^(\\d+)\\.(\\d*)\\((\\d{1,128})\\)").find(source.substring(index));if(repeating!=null){index+=repeating.value.length;val (whole,finite,recur)=repeating.destructured;val tenth=BigInteger.TEN.pow(finite.length);val recurTenth=BigInteger.TEN.pow(recur.length).subtract(BigInteger.ONE);val fixed=if(finite.isEmpty())BigInteger.ZERO else BigInteger(finite);val numerator=(BigInteger(whole).multiply(tenth).add(fixed)).multiply(recurTenth).add(BigInteger(recur));return ExactRatio.of(numerator,tenth.multiply(recurTenth))};val begin=index;var digits=0;while(index<source.length&&source[index].isDigit()){index++;digits++};if(index<source.length&&source[index]=='.'){index++;while(index<source.length&&source[index].isDigit()){index++;digits++}};require(digits>0){"Expected a decimal number"};if(index<source.length&&(source[index]=='e'||source[index]=='E')){index++;if(index<source.length&&(source[index]=='+'||source[index]=='-'))index++;val start=index;while(index<source.length&&source[index].isDigit())index++;require(index>start){"Incomplete scientific exponent"}};return ExactRatio.decimal(source.substring(begin,index))}}
private fun exactNotation(value:String):String{val map=mapOf('⁰' to '0','¹' to '1','²' to '2','³' to '3','⁴' to '4','⁵' to '5','⁶' to '6','⁷' to '7','⁸' to '8','⁹' to '9','⁻' to '-','⁺' to '+');val result=StringBuilder();var superscript=false;for(char in value){val digit=map[char];if(digit!=null){if(!superscript)result.append('^');result.append(digit);superscript=true}else{result.append(when(char){'⁄','÷'->'/';'−'->'-';else->char});superscript=false}};return result.toString()};object VisibilityScale{private val day=ExactRatio.decimal("86400");private val month=ExactRatio.decimal("2551442.8768992");private val year=ExactRatio.decimal("31556972.736");private val limits=object:LinkedHashMap<String,ExactRatio>(256,0.75f,true){override fun removeEldestEntry(eldest:MutableMap.MutableEntry<String,ExactRatio>?):Boolean=size>2048};private fun unitExact(unit:String):ExactRatio=when(unit){"DAY"->day;"MONTH"->month;"YEAR"->year;else->throw IllegalArgumentException("Invalid visibility unit")};private fun threshold(value:String,unit:String):ExactRatio{val canonical=exactNotation(value.filterNot{it.isWhitespace()});val key="$unit\u0000$canonical";return synchronized(limits){limits[key]?:ScaleExpression(canonical).parse().times(unitExact(unit)).also{limits[key]=it}}};fun normalize(raw:String,unit:String):Pair<String,String>{val compact=exactNotation(raw.filterNot{it.isWhitespace()});if(compact.isBlank())return Pair("","DAY");require(unit in listOf("DAY","MONTH","YEAR")){"Invalid visibility unit"};require(threshold(compact,unit)>=ExactRatio.decimal("0.000000001")){"Visibility thresholds smaller than 1 nanosecond cannot be displayed"};val normalized=if(compact.matches(Regex("\\+?\\d+(?:\\.\\d*)?")))BigDecimal(compact).stripTrailingZeros().toPlainString() else compact;return Pair(normalized,unit)};fun unitSeconds(unit:String):Double=when(unit){"DAY"->DAY_SECONDS;"MONTH"->MONTH_SECONDS;"YEAR"->YEAR_SECONDS;else->throw IllegalArgumentException("Invalid visibility unit")};fun visible(event:TimelineEvent,spanSeconds:Double):Boolean=forSpan(spanSeconds)(event);fun forSpan(spanSeconds:Double):(TimelineEvent)->Boolean{if(!spanSeconds.isFinite()||spanSeconds<0.0)return{it.maxScaleAmount.isBlank()};val span=ExactRatio.decimal(Math.nextDown(spanSeconds).coerceAtLeast(0.0).toString());return{it.maxScaleAmount.isBlank()||span<=threshold(it.maxScaleAmount,it.maxScaleUnit)}};fun maxSpan(amount:String,unit:String):Double=threshold(amount,unit).asDouble();fun description(amount:String,unit:String):String=if(amount.isBlank())"ALWAYS VISIBLE" else "$amount ${when(unit){"DAY"->"days";"MONTH"->"mean synodic months";else->"mean solstice years"}}"}
object ObserverClock{fun parseLongitude(input:String):BigDecimal{val raw=input.trim();val lon=if(raw.contains(',')||raw.split(Regex("\\s+")).size==2)Coordinates.parse(raw).second else BigDecimal(raw.removeSuffix("°"));require(lon>=BigDecimal("-180")&&lon<=BigDecimal("180")){"Longitude must be between -180 and 180"};return lon};fun longitudeTime(moment:Moment,longitude:BigDecimal):LocalDateTime{require(longitude>=BigDecimal("-180")&&longitude<=BigDecimal("180")){"Longitude outside -180..180"};val offset=longitude.multiply(BigDecimal("240000000000")).setScale(0,RoundingMode.HALF_UP).toBigIntegerExact();val local=moment.shift(offset);return LocalDateTime.ofInstant(Instant.ofEpochSecond(local.second,local.nano.toLong()),ZoneOffset.UTC)};fun display(moment:Moment,longitude:BigDecimal?):String{val dt=longitudeTime(moment,longitude?:BigDecimal.ZERO);val date=TimeMath.formatCivil(dt).substringBefore('T');val clock="%02d:%02d:%02d".format(java.util.Locale.ROOT,dt.hour,dt.minute,dt.second);val fraction=if(dt.nano==0)"" else "."+dt.nano.toString().padStart(9,'0').trimEnd('0');return if(longitude==null)"$date $clock$fraction · UTC · SET LONGITUDE" else "$date $clock$fraction · LMT · ${longitude.stripTrailingZeros().toPlainString()}°"}}
